import numpy as np
import mne
from mne.preprocessing import oversampled_temporal_projection


def near(name: str, a: float, b: float, rtol: float = 1e-7, atol: float = 1e-10):
    if abs(a - b) > atol + rtol * abs(b):
        print("TEST FAILED:", name, a, b)


def test_design_mne_c():
    h = mne.filter.design_mne_c_filter(1000.0, 1.0, 40.0, 0.5, 5.0)
    assert h.shape[0] == 8193
    near("abs", float(np.abs(h).sum()), 3.2099876943332113)
    near("mid", float(h[4096]), 0.07787135359453191)
    near("q", float(h[4096 + 7]), 0.042698942328843574)
    near("sum", float(h.sum()), 0.0, 1e-7, 1e-12)

test_design_mne_c()


def test_otp():
    rng = np.random.RandomState(0)
    x = rng.randn(6, 2000)
    c = rng.randn(1, 2000) * 3
    for i in range(3):
        x[i] += c[0]
    info = mne.create_info(6, 100.0, "eeg")
    info.bads = ["4"]
    raw = mne.io.RawArray(x, info)
    o = oversampled_temporal_projection(raw, duration=5.0)
    near("otp_sum", float(o._data.sum()), -334.61567486158094, 1e-6, 1e-8)
    near("otp_abs", float(np.abs(o._data).sum()), 14436.528225568582, 1e-6)
    near("otp_00", float(o._data[0, 0]), 2.314094358510709, 1e-6)
    near("otp_mid", float(o._data[2, 1000]), -0.8473769965848201, 1e-6)

test_otp()


def test_read_annotations_txt():
    p = "/tmp/typhon_preproc3_annot.txt"
    f = open(p, "w")
    f.write("# MNE-Annotations\n# orig_time : None\n# onset, duration, description\n1.5, 0.5, BAD_a\n3.0, 1.0, EDGE\n")
    f.close()
    a = mne.read_annotations(p)
    assert len(a) == 2
    assert a.onset[0] == 1.5 and a.duration[1] == 1.0
    assert a.description[1] == "EDGE"

test_read_annotations_txt()
